onTrigger.__source:
(s) => {
      // 根据路线应用不同加成
      const path = s.flags.chosen_path;
      if (path && SUCCESSION_PATHS[path]) {
        const bonuses = SUCCESSION_PATHS[path].bonuses;
        for (const k in bonuses) {
          s.resources[k] = (s.resources[k] || 0) + bonuses[k];
        }
        s.leader = SUCCESSION_PATHS[path];
      }
    }
